# -*- coding: utf-8 -*-
"""Генератор встроенных шаблонов (трудовые договоры ×4). Запуск: python3 make_templates.py <папка_вывода>"""
import sys, os, docx
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH as AL
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

OUT = sys.argv[1] if len(sys.argv) > 1 else '.'

def base():
    d = docx.Document()
    s = d.sections[0]
    s.left_margin = Cm(2.5); s.right_margin = Cm(1.5); s.top_margin = Cm(2); s.bottom_margin = Cm(2)
    st = d.styles['Normal']; st.font.name = 'Times New Roman'; st.font.size = Pt(11)
    st.element.rPr.rFonts.set(qn('w:eastAsia'), 'Times New Roman')
    st.paragraph_format.space_after = Pt(4); st.paragraph_format.space_before = Pt(0)
    return d

def para(d, text, bold=False, align=AL.JUSTIFY, indent=True, keep=False):
    p = d.add_paragraph(); p.alignment = align
    if indent and align == AL.JUSTIFY: p.paragraph_format.first_line_indent = Cm(1.25)
    r = p.add_run(text); r.bold = bold
    if keep: p.paragraph_format.keep_with_next = True
    return p

def head(d, text): 
    p = para(d, text, bold=True, align=AL.CENTER, indent=False, keep=True); p.paragraph_format.space_before = Pt(8); return p

def city_date(d):
    p = d.add_paragraph(); p.alignment = AL.LEFT
    pPr = p._p.get_or_add_pPr(); tabs = OxmlElement('w:tabs'); t = OxmlElement('w:tab')
    t.set(qn('w:val'), 'right'); t.set(qn('w:pos'), str(int(Cm(16.0).twips if hasattr(Cm(16.0),'twips') else 9071))); tabs.append(t); pPr.append(tabs)
    p.add_run('г. {{doc.city}}\t{{doc.date_long}}')
    return p

def cell_lines(cell, lines):
    first = True
    for txt, b in lines:
        p = cell.paragraphs[0] if first else cell.add_paragraph()
        first = False
        p.alignment = AL.LEFT; p.paragraph_format.space_after = Pt(2)
        r = p.add_run(txt); r.bold = b; r.font.name = 'Times New Roman'; r.font.size = Pt(11)
        r._r.get_or_add_rPr().rFonts.set(qn('w:eastAsia'), 'Times New Roman')
        p.paragraph_format.keep_with_next = True

def requisites(d, emp_extra=True):
    head(d, 'Адреса, реквизиты и подписи Сторон')
    t = d.add_table(rows=2, cols=2); t.autofit = True
    emp = [('Работодатель', True), ('{{employer.name_full}}', True), ('Юридический адрес: {{employer.addr_legal}}', False),
           ('{{employer.reg_line}}', False), ('Р/с {{employer.rs}}', False), ('{{employer.bank_name}}', False), ('К/с {{employer.ks}}', False), ('БИК {{employer.bik}}', False),
           ('Тел.: {{employer.phone}}', False), ('E-mail: {{employer.email}}', False)]
    emp2 = [('', False), ('{{employer.director_pos}}', False), ('', False), ('____________________ /{{employer.fio_short}}/', False), ('М.П.', False)]
    wrk = [('Работник', True), ('{{worker.name_full}}', True), ('Дата рождения: {{worker.birth_date}}', False),
           ('Паспорт: {{worker.passport}}', False), ('Выдан: {{worker.passport_issued}}', False), ('Дата выдачи: {{worker.passport_date}}, код подразделения {{worker.passport_code}}', False),
           ('Адрес регистрации: {{worker.addr_legal}}', False), ('СНИЛС: {{worker.snils}}', False), ('ИНН: {{worker.inn}}', False),
           ('Тел.: {{worker.phone}}', False)]
    wrk2 = [('', False), ('Работник', False), ('', False), ('____________________ /{{worker.fio_short}}/', False)]
    for rw in t.rows:
        rw._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
    cell_lines(t.rows[0].cells[0], emp); cell_lines(t.rows[0].cells[1], wrk); cell_lines(t.rows[1].cells[0], emp2); cell_lines(t.rows[1].cells[1], wrk2)
    p = d.add_paragraph(); p.paragraph_format.space_before = Pt(6)
    p.add_run('Второй экземпляр договора получен Работником «____» ____________ 20___ г. ____________ /{{worker.fio_short}}/')

PREAMBLE = '{{employer.intro|Работодатель}}, с одной стороны, и {{worker.name_full}}, {{worker.named}} в дальнейшем «Работник», с другой стороны, совместно именуемые «Стороны», заключили настоящий трудовой договор (далее — «Договор») о нижеследующем:'

def start(d, title, sub=None):
    para(d, title, bold=True, align=AL.CENTER, indent=False)
    if sub: para(d, sub, bold=True, align=AL.CENTER, indent=False)
    city_date(d)
    para(d, PREAMBLE)

def common_rights(d, n):
    head(d, f'{n}. Права и обязанности Сторон')
    para(d, f'{n}.1. Работник имеет право на: предоставление ему работы, обусловленной настоящим Договором; рабочее место, соответствующее государственным нормативным требованиям охраны труда; своевременную и в полном объёме выплату заработной платы; отдых, обеспеченный установленной ТК РФ продолжительностью рабочего времени, выходными и нерабочими праздничными днями, оплачиваемым ежегодным отпуском; обязательное социальное страхование в случаях, предусмотренных федеральными законами; иные права, предусмотренные Трудовым кодексом Российской Федерации (далее — ТК РФ), локальными нормативными актами и настоящим Договором.')
    para(d, f'{n}.2. Работник обязан: добросовестно исполнять свои трудовые обязанности, возложенные на него настоящим Договором и должностной инструкцией; соблюдать правила внутреннего трудового распорядка и иные локальные нормативные акты Работодателя, с которыми он ознакомлен под подпись; соблюдать трудовую дисциплину; выполнять установленные нормы труда; соблюдать требования по охране труда и обеспечению безопасности труда; бережно относиться к имуществу Работодателя; не разглашать охраняемую законом тайну и конфиденциальную информацию, ставшую ему известной в связи с исполнением трудовых обязанностей; незамедлительно сообщать Работодателю о возникновении ситуации, представляющей угрозу жизни и здоровью людей, сохранности имущества Работодателя.')
    para(d, f'{n}.3. Работодатель имеет право: поощрять Работника за добросовестный эффективный труд; требовать от Работника исполнения трудовых обязанностей и бережного отношения к имуществу Работодателя, соблюдения правил внутреннего трудового распорядка; привлекать Работника к дисциплинарной и материальной ответственности в порядке, установленном ТК РФ; принимать локальные нормативные акты; осуществлять иные права, предусмотренные трудовым законодательством.')
    para(d, f'{n}.4. Работодатель обязан: соблюдать трудовое законодательство и иные акты, содержащие нормы трудового права, локальные нормативные акты и условия настоящего Договора; предоставить Работнику работу, обусловленную настоящим Договором; обеспечить безопасность и условия труда, соответствующие государственным нормативным требованиям охраны труда; обеспечить Работника оборудованием, инструментами, технической документацией и иными средствами, необходимыми для исполнения трудовых обязанностей; выплачивать в полном размере причитающуюся Работнику заработную плату в сроки, установленные настоящим Договором; знакомить Работника под подпись с принимаемыми локальными нормативными актами, непосредственно связанными с его трудовой деятельностью; осуществлять обязательное социальное страхование Работника в порядке, установленном федеральными законами; исполнять иные обязанности, предусмотренные трудовым законодательством.')

def tail(d, n_resp):
    head(d, f'{n_resp}. Ответственность Сторон')
    para(d, f'{n_resp}.1. За неисполнение или ненадлежащее исполнение своих обязанностей Стороны несут ответственность в соответствии с ТК РФ и иными федеральными законами.')
    para(d, f'{n_resp}.2. Материальная ответственность Работника наступает в порядке и в пределах, установленных главой 39 ТК РФ. Договор о полной материальной ответственности заключается отдельно в случаях, предусмотренных законом.')
    para(d, f'{n_resp}.3. Работодатель, нарушивший сроки выплаты заработной платы и иных выплат, причитающихся Работнику, выплачивает их с уплатой процентов (денежной компенсации) в размере, установленном статьёй 236 ТК РФ.')
    head(d, f'{n_resp+1}. Изменение и прекращение Договора')
    para(d, f'{n_resp+1}.1. Условия Договора могут быть изменены только по соглашению Сторон, совершённому в письменной форме, за исключением случаев, предусмотренных ТК РФ.')
    para(d, f'{n_resp+1}.2. Договор может быть расторгнут по основаниям и в порядке, предусмотренным ТК РФ. Работник вправе расторгнуть Договор, предупредив об этом Работодателя в письменной форме не позднее чем за две недели, если иной срок не установлен ТК РФ или иным федеральным законом.')
    para(d, f'{n_resp+1}.3. В день прекращения Договора Работодатель обязан выдать Работнику трудовую книжку (или сведения о трудовой деятельности) и произвести с ним окончательный расчёт.')
    head(d, f'{n_resp+2}. Заключительные положения')
    para(d, f'{n_resp+2}.1. Споры и разногласия по Договору разрешаются путём переговоров, а при недостижении согласия — в порядке, установленном трудовым законодательством.')
    para(d, f'{n_resp+2}.2. Во всём, что не предусмотрено Договором, Стороны руководствуются ТК РФ, иными нормативными правовыми актами, содержащими нормы трудового права, и локальными нормативными актами Работодателя.')
    para(d, f'{n_resp+2}.3. Договор составлен в двух экземплярах, имеющих одинаковую юридическую силу, один из которых хранится у Работодателя, другой — у Работника.')
    para(d, f'{n_resp+2}.4. Работник подтверждает, что до подписания Договора ознакомлен с правилами внутреннего трудового распорядка, должностной инструкцией, положением об оплате труда и иными локальными нормативными актами, непосредственно связанными с его трудовой функцией.')
    requisites(d)

def pay(d, n, extra=''):
    head(d, f'{n}. Оплата труда')
    para(d, f'{n}.1. За выполнение трудовых обязанностей Работнику устанавливается должностной оклад в размере {{{{worker.salary_text}}}} в месяц.{extra}')
    para(d, f'{n}.2. Заработная плата выплачивается Работнику не реже чем каждые полмесяца в денежной форме в валюте Российской Федерации путём перечисления на банковский счёт, указанный Работником, в сроки, установленные правилами внутреннего трудового распорядка.')
    para(d, f'{n}.3. Из заработной платы Работника могут производиться удержания в случаях, предусмотренных законодательством Российской Федерации. Налог на доходы физических лиц удерживается Работодателем в порядке, установленном Налоговым кодексом Российской Федерации.')
    para(d, f'{n}.4. Работодатель вправе устанавливать Работнику премии, надбавки и иные поощрительные выплаты в соответствии с действующим у Работодателя положением об оплате труда.')

def social(d, n):
    head(d, f'{n}. Социальное страхование')
    para(d, f'{n}.1. Работник подлежит обязательному пенсионному, социальному и медицинскому страхованию в порядке и на условиях, установленных федеральными законами.')

def labor_open(out):
    d = base()
    start(d, 'ТРУДОВОЙ ДОГОВОР № {{doc.number}}', '(на неопределённый срок, с испытательным сроком)')
    head(d, '1. Предмет Договора')
    para(d, '1.1. Работодатель принимает Работника на работу в должности «{{worker.director_pos}}» в структурное подразделение «{{worker.department}}». Работа по настоящему Договору является для Работника основной.')
    para(d, '1.2. Трудовая функция Работника определяется должностной инструкцией, с которой Работник ознакомлен под подпись при подписании Договора.')
    para(d, '1.3. Место работы Работника: {{employer.addr_fact}}.')
    head(d, '2. Срок Договора и испытание')
    para(d, '2.1. Договор заключён на неопределённый срок. Дата начала работы: {{worker.start_date}}.')
    para(d, '2.2. В целях проверки соответствия Работника поручаемой работе ему устанавливается испытательный срок: {{worker.probation}}. Срок испытания не включает период временной нетрудоспособности и другие периоды, когда Работник фактически отсутствовал на работе (ст. 70 ТК РФ).')
    para(d, '2.3. Если срок испытания истёк, а Работник продолжает работу, он считается выдержавшим испытание, и последующее расторжение Договора допускается только на общих основаниях. При неудовлетворительном результате испытания Работодатель вправе расторгнуть Договор до истечения срока испытания, предупредив Работника в письменной форме не позднее чем за три дня с указанием причин, послуживших основанием для признания Работника не выдержавшим испытание (ст. 71 ТК РФ).')
    head(d, '3. Рабочее время и время отдыха')
    para(d, '3.1. Работнику устанавливается пятидневная рабочая неделя с двумя выходными днями (суббота и воскресенье). Продолжительность ежедневной работы — 8 часов; начало работы — 9:00, окончание — 18:00, перерыв для отдыха и питания — с 13:00 до 14:00 (в рабочее время не включается).')
    para(d, '3.2. Работнику предоставляется ежегодный основной оплачиваемый отпуск продолжительностью 28 календарных дней. Отпуск за первый год работы предоставляется по истечении шести месяцев непрерывной работы у Работодателя, по соглашению Сторон он может быть предоставлен и до истечения шести месяцев.')
    common_rights(d, 4)
    pay(d, 5, ' Оклад выплачивается за полностью отработанную норму рабочего времени.')
    social(d, 6)
    tail(d, 7)
    d.save(out)

def labor_fixed(out):
    d = base()
    start(d, 'ТРУДОВОЙ ДОГОВОР № {{doc.number}}', '(срочный)')
    head(d, '1. Предмет Договора')
    para(d, '1.1. Работодатель принимает Работника на работу в должности «{{worker.director_pos}}» в структурное подразделение «{{worker.department}}». Работа по настоящему Договору является для Работника основной.')
    para(d, '1.2. Трудовая функция Работника определяется должностной инструкцией, с которой Работник ознакомлен под подпись при подписании Договора.')
    para(d, '1.3. Место работы Работника: {{employer.addr_fact}}.')
    head(d, '2. Срок Договора')
    para(d, '2.1. Настоящий Договор является срочным трудовым договором и заключён на срок до {{worker.end_date}}. Дата начала работы: {{worker.start_date}}.')
    para(d, '2.2. Основание заключения срочного трудового договора (ст. 58, 59 ТК РФ): {{worker.term_reason}}.')
    para(d, '2.3. Договор прекращается с истечением срока его действия. О прекращении Договора в связи с истечением срока Работодатель обязан предупредить Работника в письменной форме не менее чем за три календарных дня до увольнения, за исключением случаев, когда истёк срок действия срочного трудового договора, заключённого на время исполнения обязанностей отсутствующего работника.')
    para(d, '2.4. Если ни одна из Сторон не потребовала расторжения Договора в связи с истечением срока, а Работник продолжает работу после истечения срока, условие о срочном характере Договора утрачивает силу, и Договор считается заключённым на неопределённый срок (ст. 58 ТК РФ).')
    para(d, '2.5. Испытание при приёме на работу: {{worker.probation}}. Испытание не устанавливается для лиц, заключающих трудовой договор на срок до двух месяцев; при сроке от двух до шести месяцев испытание не может превышать две недели (ст. 70 ТК РФ).')
    head(d, '3. Рабочее время и время отдыха')
    para(d, '3.1. Работнику устанавливается пятидневная рабочая неделя с двумя выходными днями (суббота и воскресенье). Продолжительность ежедневной работы — 8 часов; начало работы — 9:00, окончание — 18:00, перерыв для отдыха и питания — с 13:00 до 14:00 (в рабочее время не включается).')
    para(d, '3.2. Работнику предоставляется ежегодный основной оплачиваемый отпуск 28 календарных дней. Работникам, заключившим трудовой договор на срок до двух месяцев, отпуск предоставляется из расчёта два рабочих дня за месяц работы (ст. 291 ТК РФ).')
    common_rights(d, 4)
    pay(d, 5, ' Оклад выплачивается за полностью отработанную норму рабочего времени.')
    social(d, 6)
    tail(d, 7)
    d.save(out)

def labor_part(out):
    d = base()
    start(d, 'ТРУДОВОЙ ДОГОВОР № {{doc.number}}', '(о работе по совместительству)')
    head(d, '1. Предмет Договора')
    para(d, '1.1. Работодатель принимает Работника на работу по совместительству в должности «{{worker.director_pos}}» в структурное подразделение «{{worker.department}}».')
    para(d, '1.2. Работа по настоящему Договору является для Работника работой по совместительству, то есть выполнением другой регулярной оплачиваемой работы на условиях трудового договора в свободное от основной работы время (ст. 282 ТК РФ). Основное место работы Работника — в организации, сведения о которой он предоставил Работодателю.')
    para(d, '1.3. Трудовая функция Работника определяется должностной инструкцией, с которой Работник ознакомлен под подпись при подписании Договора. Место работы: {{employer.addr_fact}}.')
    head(d, '2. Срок Договора')
    para(d, '2.1. Договор заключён на неопределённый срок. Дата начала работы: {{worker.start_date}}.')
    para(d, '2.2. Испытание при приёме на работу: {{worker.probation}}.')
    head(d, '3. Рабочее время и время отдыха')
    para(d, '3.1. Продолжительность работы по совместительству не должна превышать четырёх часов в день и 16 часов в неделю. В дни, когда по основному месту работы Работник свободен от исполнения трудовых обязанностей, он может работать по совместительству полный рабочий день (смену) (ст. 284 ТК РФ).')
    para(d, '3.2. Режим работы: ____ часов в день, ____ дней в неделю; начало работы — ______, окончание — ______.')
    para(d, '3.3. Ежегодный оплачиваемый отпуск предоставляется Работнику одновременно с отпуском по основному месту работы. Если на работе по совместительству Работник не отработал шести месяцев, отпуск предоставляется авансом (ст. 286 ТК РФ). Продолжительность отпуска — 28 календарных дней.')
    para(d, '3.4. Работник обязан предъявить Работодателю справку с основного места работы о характере и условиях труда, если работа по совместительству связана с вредными и (или) опасными условиями труда или выполняется на тяжёлых работах (ст. 283 ТК РФ).')
    common_rights(d, 4)
    pay(d, 5, ' Оплата труда при работе на условиях неполного рабочего времени производится пропорционально отработанному времени либо в зависимости от выполненного объёма работ (ст. 285 ТК РФ).')
    social(d, 6)
    tail(d, 7)
    d.save(out)

def labor_remote(out):
    d = base()
    start(d, 'ТРУДОВОЙ ДОГОВОР № {{doc.number}}', '(о дистанционной работе)')
    head(d, '1. Предмет Договора')
    para(d, '1.1. Работодатель принимает Работника на дистанционную работу в должности «{{worker.director_pos}}» в структурное подразделение «{{worker.department}}». Работа по настоящему Договору является для Работника основной.')
    para(d, '1.2. Дистанционной признаётся работа, выполняемая вне места нахождения Работодателя, вне стационарного рабочего места, с использованием информационно-телекоммуникационных сетей, в том числе сети «Интернет», для выполнения трудовой функции и для взаимодействия Сторон по вопросам, связанным с её выполнением (глава 49.1 ТК РФ).')
    para(d, '1.3. Местом осуществления трудовой функции является место, выбранное Работником по своему усмотрению: адрес проживания Работника — {{worker.addr_fact}}. Об изменении места работы Работник уведомляет Работодателя в письменном виде или в электронной форме.')
    head(d, '2. Срок Договора')
    para(d, '2.1. Договор заключён на неопределённый срок. Дата начала работы: {{worker.start_date}}.')
    para(d, '2.2. Испытание при приёме на работу: {{worker.probation}}.')
    head(d, '3. Условия дистанционной работы')
    para(d, '3.1. Работодатель предоставляет Работнику (либо Работник использует с письменного согласия или ведома Работодателя и за выплачиваемую компенсацию) оборудование, программно-технические средства, средства защиты информации и иные средства, необходимые для выполнения трудовой функции. Порядок и размер компенсации за использование личного имущества Работника определяются дополнительным соглашением к Договору (ст. 312.6 ТК РФ).')
    para(d, '3.2. Взаимодействие Сторон осуществляется в электронной форме с использованием электронной почты Работодателя и Работника ({{worker.email}}), корпоративных мессенджеров и иных информационных систем. Обмен документами, непосредственно связанными с трудовой деятельностью, возможен в форме электронных документов, подписанных усиленной квалифицированной электронной подписью или иным способом, определённым соглашением Сторон (ст. 312.2 ТК РФ).')
    para(d, '3.3. Работник самостоятельно определяет режим рабочего времени и времени отдыха, при этом обязуется быть на связи с Работодателем с ______ до ______ в рабочие дни. Продолжительность рабочего времени не может превышать норм, установленных ТК РФ.')
    para(d, '3.4. Работник обязан соблюдать требования информационной безопасности, обеспечивать сохранность и конфиденциальность сведений, ставших ему известными при выполнении трудовой функции, а также не передавать третьим лицам пароли и средства доступа к информационным системам Работодателя.')
    para(d, '3.5. Работодатель обязан обеспечить Работнику безопасные условия труда в части, касающейся организации работы Работника на удалённом рабочем месте, провести обучение по охране труда и ознакомить с требованиями охраны труда при дистанционной работе (ст. 312.3 ТК РФ).')
    para(d, '3.6. Ежегодный основной оплачиваемый отпуск — 28 календарных дней. Отпуск за первый год работы предоставляется по истечении шести месяцев непрерывной работы у Работодателя.')
    common_rights(d, 4)
    pay(d, 5, ' Заработная плата перечисляется на банковский счёт Работника, указанный им в письменном заявлении.')
    social(d, 6)
    tail(d, 7)
    d.save(out)

for fn, name in [(labor_open, 'trud_bessrochnyj'), (labor_fixed, 'trud_srochnyj'), (labor_part, 'trud_sovmestitelstvo'), (labor_remote, 'trud_distancionnyj')]:
    fn(os.path.join(OUT, name + '.docx'))
print('ok')
